def fib(n: int) -> int:
    a, b = 0, 1
    for _ in range(n):
        a, b = b, a + b
    return a


def gcd(a: int, b: int) -> int:
    while b:
        a, b = b, a % b
    return a


def is_prime(n: int) -> bool:
    if n < 2:
        return False
    i = 2
    while i * i <= n:
        if n % i == 0:
            return False
        i += 1
    return True


def binary_search(items: list[int], target: int) -> int:
    lo, hi = 0, len(items) - 1
    while lo <= hi:
        mid = (lo + hi) // 2
        if items[mid] == target:
            return mid
        if items[mid] < target:
            lo = mid + 1
        else:
            hi = mid - 1
    return -1


def main() -> None:
    print("fib(10) =", fib(10))
    print("gcd(54, 24) =", gcd(54, 24))
    primes = [n for n in range(2, 50) if is_prime(n)]
    print("primes:", primes)
    squares = [n * n for n in range(1, 20)]
    print("index of 144:", binary_search(squares, 144))


if __name__ == "__main__":
    main()

